constexpr float kPi = 3.14159265358979323846f;
constexpr float kTwoPi = kPi * 2.0f;

inline NVGcolor ToNvg(ColorRgba c) noexcept {
    return nvgRGBA(c.r, c.g, c.b, c.a);
}

inline NVGcolor ToNvgAlphaF(ColorRgba c, float alpha01) noexcept {
    const float clamped = std::clamp(alpha01, 0.0f, 1.0f);
    return nvgRGBA(c.r, c.g, c.b, static_cast<uint8_t>(std::round(clamped * 255.0f)));
}

